using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
namespace DoomSNESed {
    public sealed class MusicNote {public double Start,End;public int Key,Velocity,Program,Channel;}
    public sealed class ImportedMusic {public string Name,Report;public double Seconds,QuarterSeconds;public List<MusicNote> Notes=new List<MusicNote>();}
    public sealed class MusicReplacement {public string Map,Name,Report;public byte[] Sequence;public int Voices,VoiceBudget=6;public double Seconds;public ImportedMusic Source;public MusicSettings Settings;}
    public sealed class SoundReplacement {public int Wave;public string Name,Report;public byte[] Data;public bool Loop;public int Rate=11025,Effect=-1;}
    public sealed class AudioProject {public List<MusicReplacement> Music=new List<MusicReplacement>();public List<SoundReplacement> Sounds=new List<SoundReplacement>();public bool Any {get{return Music.Count>0||Sounds.Count>0;}}}
    public static class MusicImport {
        sealed class Event {public long Tick;public int Channel,Kind,A,B,Order;}
        static int BE16(byte[] b,int p){return (b[p]<<8)|b[p+1];}
        static int BE32(byte[] b,int p){long n=((long)b[p]<<24)|((long)b[p+1]<<16)|((long)b[p+2]<<8)|b[p+3];Bin.Require(n<=int.MaxValue,"MIDI chunk is too large.");return (int)n;}
        static int Vlq(byte[] b,ref int p,int end){int n=0;for(int i=0;i<4;i++){Bin.Require(p<end,"Truncated music timing.");int v=b[p++];n=(n<<7)|(v&127);if(v<128)return n;}throw new InvalidDataException("Invalid music timing value.");}
        public static ImportedMusic Read(string path){Bin.Require(new FileInfo(path).Length<=16*1024*1024,"Music input exceeds 16 MiB.");byte[] b=File.ReadAllBytes(path);Bin.Require(b.Length>=16&&b.Length<=16*1024*1024,"Music input must be 16 bytes to 16 MiB.");return Encoding.ASCII.GetString(b,0,4)=="MThd"?Midi(b,Path.GetFileName(path)):Mus(b,Path.GetFileName(path));}
        static ImportedMusic Midi(byte[] b,string name){Bin.Require(BE32(b,4)>=6&&8L+BE32(b,4)<=b.Length,"Invalid MIDI header.");int format=BE16(b,8),tracks=BE16(b,10),division=BE16(b,12);Bin.Require(format<=1&&tracks>0&&tracks<=256&&division>0&&division<32768,"Use MIDI format 0 or 1 with PPQN timing; SMPTE and asynchronous format 2 are unsupported.");var events=new List<Event>();int p=8+BE32(b,4),order=0;for(int t=0;t<tracks;t++){Bin.Require(p+8<=b.Length&&Encoding.ASCII.GetString(b,p,4)=="MTrk","Missing MIDI track.");int size=BE32(b,p+4);p+=8;Bin.Require(size<=b.Length-p,"Truncated MIDI track.");int end=p+size,running=0;long tick=0;while(p<end){tick+=Vlq(b,ref p,end);Bin.Require(tick<=1000000000,"Music timeline is too long.");Bin.Require(p<end,"Truncated MIDI event.");int status=b[p];if(status>=128){p++;if(status<240)running=status;else running=0;}else{Bin.Require(running!=0,"Invalid MIDI running status.");status=running;}if(status==255){Bin.Require(p<end,"Truncated MIDI metadata.");int type=b[p++],length=Vlq(b,ref p,end);Bin.Require(length<=end-p,"Truncated MIDI metadata payload.");if(type==81&&length==3){int tempo=(b[p]<<16)|(b[p+1]<<8)|b[p+2];Bin.Require(tempo>0,"Invalid MIDI tempo.");events.Add(new Event{Tick=tick,Kind=256,A=tempo,Order=order++});}p+=length;if(type==47)break;continue;}if(status==240||status==247){int length=Vlq(b,ref p,end);Bin.Require(length<=end-p,"Truncated SysEx event.");p+=length;continue;}Bin.Require(status>=128&&status<240,"Unsupported MIDI status.");int kind=status&240,channel=status&15,count=kind==192||kind==208?1:2;Bin.Require(p+count<=end,"Truncated MIDI event.");int a=b[p++],v=count==2?b[p++]:0;Bin.Require(a<128&&v<128,"Invalid MIDI event data.");events.Add(new Event{Tick=tick,Kind=kind,Channel=channel,A=a,B=v,Order=order++});Bin.Require(events.Count<=500000,"Music contains too many events.");}p=end;}return Interpret(events,division,false,name);}
        static ImportedMusic Mus(byte[] b,string name){Bin.Require(Encoding.ASCII.GetString(b,0,4)=="MUS\x1a","Choose a MIDI (.mid) or Doom MUS (.mus) file.");int size=Bin.U16(b,4),p=Bin.U16(b,6),end=p+size;Bin.Require(p>=16&&end<=b.Length,"Invalid MUS score range.");var events=new List<Event>();int[] velocity=Enumerable.Repeat(64,16).ToArray();long tick=0;int order=0;bool finished=false;while(p<end){int descriptor=b[p++],type=(descriptor>>4)&7,c=descriptor&15;int channel=c==15?9:c>=9?c+1:c;Bin.Require(channel<16,"Invalid MUS channel.");if(type==6){finished=true;break;}Bin.Require(p<end,"Truncated MUS event.");int a=b[p++],kind=0,v=0;if(type==0){kind=128;a&=127;}else if(type==1){kind=144;if((a&128)!=0){Bin.Require(p<end&&b[p]<128,"Invalid MUS note velocity.");velocity[c]=b[p++];}a&=127;v=velocity[c];}else if(type==2){kind=224;v=a>>1;a=(a&1)*64;}else if(type==3){kind=176;a=a==10?120:a==11?123:a==14?121:123;}else if(type==4){Bin.Require(p<end,"Truncated MUS controller.");v=b[p++];Bin.Require(v<128,"Invalid MUS controller value.");if(a==0){kind=192;a=v;v=0;}else{int[] controls={0,0,1,7,10,11,91,93,64,67};Bin.Require(a<controls.Length,"Unknown MUS controller.");kind=176;a=controls[a];}}else throw new InvalidDataException("Unsupported MUS event type "+type+".");events.Add(new Event{Tick=tick,Channel=channel,Kind=kind,A=a,B=v,Order=order++});if((descriptor&128)!=0)tick+=Vlq(b,ref p,end);Bin.Require(events.Count<=500000&&tick<=140*3600,"MUS score is too long.");}Bin.Require(finished,"MUS score has no end marker.");return Interpret(events,140,true,name);}
        static ImportedMusic Interpret(List<Event> events,int division,bool mus,string name){var result=new ImportedMusic{Name=name};int[] program=new int[16],volume=Enumerable.Repeat(127,16).ToArray(),expression=Enumerable.Repeat(127,16).ToArray(),bend=Enumerable.Repeat(8192,16).ToArray();bool[] sustain=new bool[16];var held=new Dictionary<int,MusicNote>();var released=new List<MusicNote>();long previous=0;double seconds=0;int tempo=500000;var tempos=new HashSet<int>();Action<MusicNote,double> finish=(note,time)=>{note.End=Math.Max(time,note.Start+.001);result.Notes.Add(note);};foreach(Event e in events.OrderBy(e=>e.Tick).ThenBy(e=>e.Order)){seconds+=(e.Tick-previous)*(mus?1.0/division:tempo/(1000000.0*division));previous=e.Tick;Bin.Require(seconds<=3600,"Music exceeds one hour.");int c=e.Channel,key=c*128+e.A;if(e.Kind==256){tempo=e.A;continue;}if(e.Kind==192)program[c]=e.A;else if(e.Kind==224)bend[c]=e.A+(e.B<<7);else if(e.Kind==176){if(e.A==7)volume[c]=e.B;else if(e.A==11)expression[c]=e.B;else if(e.A==64){bool down=e.B>=64;if(!down)foreach(var note in released.Where(n=>n.Channel==c).ToArray()){finish(note,seconds);released.Remove(note);}sustain[c]=down;}else if(e.A==120||e.A==123){foreach(var pair in held.Where(n=>n.Value.Channel==c).ToArray()){finish(pair.Value,seconds);held.Remove(pair.Key);}foreach(var note in released.Where(n=>n.Channel==c).ToArray()){finish(note,seconds);released.Remove(note);}}}else if(e.Kind==144&&e.B>0){tempos.Add(tempo);MusicNote prior;if(held.TryGetValue(key,out prior))finish(prior,seconds);int pitch=Math.Max(0,Math.Min(127,e.A+(int)Math.Round((bend[c]-8192)/4096.0)));held[key]=new MusicNote{Start=seconds,Channel=c,Key=pitch,Velocity=e.B*volume[c]*expression[c]/(127*127),Program=program[c]};}else if(e.Kind==128||e.Kind==144){MusicNote note;if(held.TryGetValue(key,out note)){held.Remove(key);if(sustain[c])released.Add(note);else finish(note,seconds);}}}foreach(var note in held.Values.Concat(released))finish(note,seconds+.1);Bin.Require(result.Notes.Count>0,"This score contains no playable notes.");result.QuarterSeconds=!mus&&tempos.Count==1?tempos.First()/1000000.0:0;result.Seconds=result.Notes.Max(n=>n.End);result.Report=result.Notes.Count+" notes; "+result.Seconds.ToString("0.00")+" s. Tempo changes, sustain, note velocities and channel volume are read. Pitch bends are approximated at note onset; modulation, reverb and SysEx are omitted.";return result;}
        static void Rest(List<byte> bytes,int units){while(units>0){int n=Math.Min(units,32);bytes.Add((byte)(191+n));units-=n;}}
        static int Instrument(MusicNote note,out int pitch){int patch=note.Channel==9?(note.Key==35||note.Key==36?46:note.Key==38||note.Key==40?42:note.Key==42||note.Key==44||note.Key==46?47:41):note.Program>=32&&note.Program<40?45:44;pitch=NativeVoicing.Pitch(note,patch);return patch;}
        // Timer 1: 1.024 MHz / 128 / 160. The driver's 8-bit tempo
        // accumulator advances a score tick on carry, rather than at 30 Hz.
        public const double TickRate=50.0*255/256;
        static int Tick(double seconds,int grid){return (int)Math.Round(Math.Round(seconds*grid)/grid*TickRate);}
        static double Priority(MusicNote n,MusicSettings settings){var assignment=settings.Assignments.FirstOrDefault(a=>a.Channel==n.Channel&&a.Program==n.Program&&(a.Key<0||a.Key==n.Key));double manual=assignment==null?0:assignment.Priority*16;double role=n.Channel==9?(n.Key==35||n.Key==36||n.Key==38||n.Key==40?28:-12):n.Program>=32&&n.Program<40?24:n.Program>=24&&n.Program<32?18:n.Program>=88&&n.Program<104?-12:8;return n.Velocity+role+manual;}
        public static MusicReplacement Convert(ImportedMusic input,string map,int maxVoices,double maxSeconds,bool loop,MusicSettings settings=null){
            settings=settings??new MusicSettings();Bin.Require(settings.Grid>=5&&settings.Grid<=50&&settings.VelocitySteps>=1&&settings.VelocitySteps<=8,"Invalid music optimization settings.");
            Bin.Require(settings.ReleaseMs>=0&&settings.ReleaseMs<=500,"Tail protection must be between 0 and 500 ms.");
            Bin.Require(maxVoices>=1&&maxVoices<=8,"Music supports 1..8 voices. Six leaves two hardware voices available for effects; eight shares every voice with effects.");
            var voices=Enumerable.Range(0,maxVoices).Select(i=>new List<MusicNote>()).ToArray();int dropped=0,tailReuses=0;
            double duration=maxSeconds>0?Math.Min(maxSeconds,input.Seconds):input.Seconds;var clock=MusicClock.Choose(input,duration);int releaseTicks=settings.NaturalRelease?(int)Math.Round(settings.ReleaseMs*clock.Rate/1000):0;
            int totalUnits=Math.Max(1,clock.Tick(duration));
            var notes=input.Notes.Where(n=>n.Velocity>0&&!MusicBank.Muted(settings,n)&&n.Start<duration).Select(n=>new MusicNote{Start=clock.Tick(n.Start),End=Math.Min(totalUnits,Math.Max(clock.Tick(n.Start)+1,clock.Tick(Math.Min(n.End,duration)))),Key=n.Key,Velocity=n.Velocity,Program=n.Program,Channel=n.Channel}).Where(n=>n.End>n.Start).OrderBy(n=>n.Start).ThenByDescending(n=>Priority(n,settings));
            foreach(var note in notes){
                // Closed/pedal hi-hats stop an open hat, as in a physical kit.
                if(note.Channel==9&&(note.Key==42||note.Key==44))foreach(var v in voices)if(v.Count>0){var old=v[v.Count-1];if(old.Channel==9&&old.Key==46&&old.End>note.Start)old.End=note.Start;}
                int voice=Array.FindIndex(voices,v=>v.Count>0&&v[v.Count-1].End+releaseTicks<=note.Start&&v[v.Count-1].Channel==note.Channel&&v[v.Count-1].Program==note.Program);
                if(voice<0)voice=Array.FindIndex(voices,v=>v.Count==0||v[v.Count-1].End+releaseTicks<=note.Start);
                // A fading tail is cheaper to reuse than a still-held MIDI note.
                // Prefer another free voice so rapid passages do not repeatedly
                // chop the same instrument's release envelope.
                if(voice<0){voice=Enumerable.Range(0,maxVoices).Where(i=>voices[i].Last().End<=note.Start).OrderBy(i=>voices[i].Last().End).DefaultIfEmpty(-1).First();if(voice>=0)tailReuses++;}
                if(voice<0){voice=Enumerable.Range(0,maxVoices).OrderBy(i=>Priority(voices[i].Last(),settings)-Math.Min(18,(note.Start-voices[i].Last().Start)*.15)).First();var previous=voices[voice].Last();dropped++;if(note.Start-previous.Start<3&&Priority(note,settings)<Priority(previous,settings)+32)continue;if(Priority(previous,settings)-Math.Min(18,(note.Start-previous.Start)*.15)>=Priority(note,settings))continue;previous.End=note.Start;}
                voices[voice].Add(note);
            }
            voices=voices.Select(v=>v.Where(n=>n.End>n.Start).ToList()).Where(v=>v.Count>0).ToArray();if(voices.Length==0)voices=new[]{new List<MusicNote>()};
            int origin=settings.Origin,limit=0xb490;var data=new List<byte>();data.Add((byte)voices.Length);for(int i=0;i<voices.Length*2;i++)data.Add(0);
            for(int voice=0;voice<voices.Length;voice++){
                int pointer=origin+data.Count;data[1+voice*2]=(byte)pointer;data[2+voice*2]=(byte)(pointer>>8);data.AddRange(new byte[]{0xe9,0xf8,0xf3,0x80,0xe6,0xed,0xff});if(voice==0)data.AddRange(new byte[]{0xfa,(byte)clock.Tempo});
                int cursor=0,instrument=-1,volume=-1,lastKey=-1;
                for(int noteIndex=0;noteIndex<voices[voice].Count;noteIndex++){var note=voices[voice][noteIndex];
                    int start=(int)note.Start,end=(int)note.End;if(start>cursor)Rest(data,start-cursor);
                    int key,patch=Instrument(note,out key);var assignment=settings.Assignments.FirstOrDefault(a=>a.Channel==note.Channel&&a.Program==note.Program&&(a.Key<0||a.Key==note.Key));
                    if(assignment!=null){patch=assignment.Patch;key=Math.Max(0,Math.Min(127,NativeVoicing.Pitch(note,patch)+assignment.Transpose));}
                    int gain=Math.Max(8,Math.Min(64,(int)Math.Round(note.Velocity*(double)settings.VelocitySteps/127)*(64/settings.VelocitySteps)));
                    if(patch!=instrument){data.Add(0xf5);data.Add((byte)patch);instrument=patch;lastKey=-1;}if(gain!=volume){data.Add(0xf2);data.Add((byte)gain);volume=gain;}
                    int length=end-start;while(length>0){int count=Math.Min(length,255),delta=key-lastKey;if(lastKey>=0&&delta>=-8&&delta<=7&&count<=8)data.Add((byte)((delta+8)*8+count-1));else if(key>=32&&key<=95)data.AddRange(new byte[]{(byte)(key+96),(byte)count});else data.AddRange(new byte[]{0xef,(byte)key,(byte)count});lastKey=key;length-=count;}
                    // A following rest, note attack or F0 already performs the
                    // retail envelope release. Avoid a redundant command after
                    // every note; this saves space for timing and dynamics.
                    // F9 resets track ownership, so release explicitly before
                    // a loop with no trailing rest.
                    if(!settings.NaturalRelease)data.Add(0xe8);
                    else if(loop&&noteIndex==voices[voice].Count-1&&end==totalUnits)data.Add(0xea);
                    cursor=end;
                }
                if(cursor<totalUnits)Rest(data,totalUnits-cursor);data.Add(loop?(byte)0xf9:(byte)0xf0);
            }
            Bin.Require(origin+data.Count<=limit,"Music needs "+data.Count+" SPC bytes; this native instrument bank has "+(limit-origin)+". Reduce voices, shorten the score, or remove dense passages.");
            return new MusicReplacement{Map=map,Name=input.Name,Source=input,Settings=settings,Sequence=data.ToArray(),Voices=voices.Length,VoiceBudget=maxVoices,Seconds=duration,Report=input.Report+"\r\nNative conversion: "+voices.Length+" / "+maxVoices+" allocated voices; "+input.Notes.Select(n=>n.Channel).Distinct().Count()+" source MIDI channels; "+data.Count+" / "+(limit-origin)+" sequence bytes; single-pass native timing; "+clock.NativeRate.ToString("0.#####")+" Hz retail SPC clock (tempo "+clock.Tempo+"); "+(clock.Tempo==255?"finest absolute timing":"beat-aligned timing, "+((clock.NativeRate/clock.Rate-1)*100).ToString("+0.000;-0.000;0")+"% tempo rounding")+"; "+settings.VelocitySteps+" velocity levels; "+dropped+" overlapping notes omitted or shortened. Lead/bass and kick/snare priority; "+(settings.NaturalRelease?"native envelope releases; "+(settings.ReleaseMs>0?settings.ReleaseMs+" ms extra voice reservation; "+tailReuses+" fading tails reused under voice pressure.":"normal voice reuse (release envelopes still ring)."):"tight hard-gated note endings.")+" Unused tracks are omitted when the source has fewer overlapping notes; notes are never duplicated to fill voices. Sustains longer than 255 ticks retrigger. Uses native bank "+settings.Bank+". "+(loop?"Loops.":"Stops at end.")};
        }
    }
}


